SELECT *
FROM tms_corporate_action


        AND remark = #{req.remark}


        AND action_type = #{req.actionType}


        AND trade_numbers LIKE CONCAT('%', #{req.tradeNumber}, '%')


        AND action_no LIKE CONCAT('%', #{req.actionNumber}, '%')


        AND value_date >= #{req.valueDateStart}


        AND value_date <= #{req.valueDateEnd}


        AND currency = #{req.currency}


        AND settlement_amount >= #{req.amountMin}


        AND settlement_amount <= #{req.amountMax}


        AND isin = #{req.isin}


        AND payment_status = #{req.paymentStatus}


        AND journal_status = #{req.journalStatus}


        AND journal_sequence LIKE CONCAT('%', #{req.journalSequence}, '%')


ORDER BY create_time DESC
